package main

import (
	"errors"
	"fmt"
)

func remaining(total, done int) (int, error) {
	if total < 0 || done < 0 || done > total {
		return 0, errors.New("invalid count")
	}
	return total - done, nil
}

func main() {
	left, err := remaining(6, 2)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(left)
}

package main

import "fmt"

func main() {
	order := []int{7, 4}
	order = append(order, 9)
	done := map[int]bool{7: true, 4: false}
	for _, id := range order {
		value, ok := done[id]
		fmt.Println(id, value, ok)
	}
}

package main

import (
	"encoding/json"
	"fmt"
)

type Task struct {
	ID int `json:"id"`
	Title string `json:"title"`
	Completed bool `json:"completed"`
}

func main() {
	task := Task{ID: 1, Title: "Read"}
	data, err := json.Marshal(task)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(string(data))
}
